import type { DiagramElement, Figure } from './figures';
import { C, FILL, bx, lb, ar, ln, ci, pg, show, band, fresh, cover } from './diagram-kit';

// 月例模試 2027年1月号（担当A・k01〜k25）高校受験 理科の「動く図解」。キーは問題ID。座標は 320×240。
// 図は上（y＜165）に描き、下の帯（y≥170）に短い結論を出す。

/** 文字の見積もり幅（全角＝1、半角＝0.55）。 */
const tw = (s: string): number => Array.from(s).reduce((a, ch) => a + (ch.charCodeAt(0) < 256 ? 0.55 : 1), 0);

/** 下の帯に一言（前のスライドの帯は白でおおいかくして書きかえる）。長さに合わせて文字の大きさを選ぶ。 */
const m = (text: string, color: string = C.main, fill: string = FILL.warm, size = 13): DiagramElement[] => {
  const lines = text.split('\n');
  const w = Math.max(...lines.map(tw));
  let s = size;
  while (s > 10 && w * s > 262) s -= 1;
  return band(170, bx(20, 176, 280, 34, text, color, fill, s));
};

/** 円（に近い多角形）。ラベルをのせても「箱の上」と判定されないように、多角形で描く。 */
const circlePts = (cx: number, cy: number, r: number, n = 18): [number, number][] =>
  Array.from({ length: n }, (_, i) => [Math.round((cx + r * Math.cos((2 * Math.PI * i) / n)) * 10) / 10, Math.round((cy + r * Math.sin((2 * Math.PI * i) / n)) * 10) / 10] as [number, number]);
const rect = (x0: number, y0: number, x1: number, y1: number, color?: string, fill?: string): DiagramElement =>
  pg([[x0, y0], [x1, y0], [x1, y1], [x0, y1]], color, fill);

/** 円を線分でえがく（塗りなし）。 */
const ring = (cx: number, cy: number, r: number, color: string, n = 24, width = 1.6): DiagramElement[] => {
  const pts = circlePts(cx, cy, r, n);
  return pts.map((p, i) => ln(p[0], p[1], pts[(i + 1) % n][0], pts[(i + 1) % n][1], color, false, width));
};

/** 正弦波（線分で描く）。1周期を pts 個の線分で近似する。 */
const wave = (x0: number, y0: number, amp: number, periods: number, len: number, color: string, pts = 8, width = 2): DiagramElement[] => {
  const out: DiagramElement[] = [];
  const total = periods * pts;
  const at = (i: number): [number, number] => [Math.round((x0 + (len * i) / total) * 10) / 10, Math.round((y0 - amp * Math.sin((2 * Math.PI * i) / pts)) * 10) / 10];
  for (let i = 0; i < total; i += 1) {
    const a = at(i);
    const b = at(i + 1);
    out.push(ln(a[0], a[1], b[0], b[1], color, false, width));
  }
  return out;
};

