// k25 金属の性質
const k25Rows = (hi: number[], color: string = C.green, fill: string = FILL.green): DiagramElement[] => {
  const rows = ['P　磁石につく　電気を通す　みがくと光る', 'Q　磁石につかない　電気を通す　赤みの光沢　たたくと広がる', 'R　磁石につかない　電気を通す　黒色　たたくとくだける', 'S　磁石につかない　電気を通さない　熱を伝えにくい'];
  return rows.map((t, i) => bx(10, 12 + 36 * i, 300, 28, t, hi.includes(i) ? color : C.gray, hi.includes(i) ? fill : FILL.gray, 10));
};
const f25 = show([
  { note: '4つの物質P〜Sの性質を調べました。この中から、金属を選びます。',
    add: [...k25Rows([]), ...m('4つの物質P〜Sの性質')] },
  { note: '金属には、共通の性質があります。電気をよく通す、熱をよく伝える、みがくと金属光沢が出る、たたくと広がり（展性）・引っぱると伸びる（延性）、の4つです。',
    add: fresh(bx(10, 20, 145, 32, '電気をよく通す', C.blue, FILL.blue, 12), bx(165, 20, 145, 32, '熱をよく伝える', C.blue, FILL.blue, 12), bx(10, 62, 145, 32, '金属光沢がある', C.blue, FILL.blue, 12), bx(165, 62, 145, 32, '展性・延性がある', C.blue, FILL.blue, 12), ...m('金属に共通の性質')) },
  { note: '❓金属はどれでしょう。Pは、電気を通し、みがくと光ります。Qは、電気を通し、光沢があり、たたくと広がります。この2つは金属の性質をもっています。(1)の答えは、PとQです。',
    add: fresh(...k25Rows([0, 1]), ...m('(1) 金属：PとQ', C.green, FILL.green)) },
  { note: '❓Rは金属でしょうか。Rは電気を通しますが、黒色で、たたくとくだけます。金属ならたたくと広がるはずなので、展性がありません。電気を通すだけでは、金属とは決まりません。Rは金属ではありません。(2)の答えです。',
    add: fresh(...k25Rows([2], C.red, FILL.red), ...m('(2) Rは金属でない', C.red, FILL.red)) },
  { note: '❓磁石につくことは、金属に共通の性質でしょうか。Pは磁石につきますが、Qは金属なのに磁石につきません。鉄などの一部の金属だけが磁石につくので、金属に共通の性質ではありません。(3)の答えです。',
    add: fresh(...k25Rows([0, 1]), bx(10, 12, 300, 28, 'P　磁石につく　電気を通す　みがくと光る', C.blue, FILL.blue, 10), ...m('(3) 共通の性質ではない', C.blue, FILL.blue)) },
  { note: '❓Rを、酸素中で燃やすと、何ができるでしょう。Rは黒色で電気を通す、炭素（黒鉛）です。炭素は燃えると二酸化炭素になり、石灰水を白くにごらせます。(4)の答えです。',
    add: fresh(bx(10, 44, 80, 40, 'R\n炭素（黒鉛）', C.gray, FILL.gray, 10), lb(100, 64, '＋', 16, C.gray, 'middle', true), bx(110, 44, 70, 40, '酸素', C.blue, FILL.blue, 12), ar(184, 64, 214, 64, C.gray), bx(216, 44, 94, 40, '二酸化炭素', C.green, FILL.green, 11), ...m('(4) 二酸化炭素', C.green, FILL.green)) },
  { note: '確かめます。金属は4つの性質（電気・熱・光沢・展性延性）をすべてもちます。PとQは金属の性質に合い、Rだけが展性がなくて外れました。',
    add: fresh(...k25Rows([0, 1]), ...m('金属の4つの性質で判定', C.green, FILL.green)) },
], '答え：(1) PとQ (2) 金属でない。たたくとくだけるから (3) 共通の性質ではない (4) 二酸化炭素');

